// План specs/admin-access.md, 5.5 (кейс AA-12). Пользователь «בדיקה». Варианты адреса из AA-03 / AA-07. Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL } from './access-helpers';
import { CRUMB, USER_STATE, expectCrumb, expectNoScreenNameFlash, installCrumbRecorder } from './crumb-helpers';

test.use({ storageState: USER_STATE });

const VARIANTS = [
  { lang: 'en', url: '/supportinbox/' },
  { lang: 'he', url: '/SupportInbox' },
  { lang: 'en', url: '/adminpanel?tab=plans' },
  { lang: 'he', url: '/AdminPanel/' },
] as const;

test.describe('Крошки без названия закрытого экрана — обычный пользователь (#26087e6e)', () => {
  for (const v of VARIANTS) {
    test(`Non-admin redirected from ${v.url} never sees the closed screen name in breadcrumbs, title or page (${v.lang.toUpperCase()}) #26087e6e @desktop @prod-safe`, async ({ page }) => {
      await setLanguage(page, v.lang);
      await installCrumbRecorder(page);

      await page.goto(v.url);
      await expect(page).toHaveURL(DASHBOARD_URL);
      await expectCrumb(page, CRUMB[v.lang].home);
      await expectNoScreenNameFlash(page, CRUMB[v.lang].home);
    });
  }
});
